import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.CNDaxUod.js";const g=JSON.parse('{"title":"Web app","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md"}'),r={name:"guide/dashboard.md"};function n(i,e,d,h,l,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="web-app" tabindex="-1">Web app <a class="header-anchor" href="#web-app" aria-label="Permalink to &quot;Web app&quot;">​</a></h1><p>AsyncUp&#39;s console lives at <strong><code>https://&lt;your-host&gt;/app</code></strong>. It is a single-page app served by the same process as the Chat bot and the JSON API, so there is nothing extra to deploy.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>The sign-in page offers whichever methods are configured:</p><table tabindex="0"><thead><tr><th>Method</th><th>Who lands where</th></tr></thead><tbody><tr><td><strong>Sign in with Google</strong></td><td>Workspace admins get the console; everyone else gets their own page</td></tr><tr><td><strong>Continue with SSO</strong> (SAML)</td><td>Same split, with the admin role taken from the IdP group attribute</td></tr><tr><td><strong>Operator token</strong> (<code>DASHBOARD_TOKEN</code>)</td><td>The console, acting as the workspace operator. Kept in the browser tab only; switch it off under <em>Settings › Sign-in &amp; SSO</em> once a real method works</td></tr></tbody></table><p>On a fresh install an admin lands in the <strong>guided setup</strong> (<code>/app/setup</code>): Cloud project → service account → Chat app configuration with a live check for the first signed event → optional sign-in → the first standup from a template, run immediately. Progress is saved as you go; the welcome page detects a working Chat connection and skips straight to the standup step.</p><h2 id="what-s-there" tabindex="-1">What&#39;s there <a class="header-anchor" href="#what-s-there" aria-label="Permalink to &quot;What&#39;s there&quot;">​</a></h2><ul><li><strong>Standups</strong> — stats strip (submitted today, participation, open blockers, missing), the table, and per standup: <strong>Overview</strong> (today&#39;s run polled live, recent runs, open blockers, schedule), <strong>History</strong> (every run with full answers, CSV export), <strong>Insights</strong> (participation by person, mood and blocker charts) and <strong>Settings</strong> (schedule, questions, mood, roster, escalation, webhook with a signed test, digest, archive).</li><li><strong>Blockers</strong> — every open, acknowledged or resolved blocker across the standups you can see, with filters and the same actions as in Chat.</li><li><strong>Reports</strong> — participation, team mood and blockers over 4, 8 or 12 weeks, for all standups or one.</li><li><strong>Team</strong> — everyone on a roster with role, standups, timezone and status; roster changes with confirmation.</li><li><strong>Settings</strong> — General, Google Chat (with live verification), Sign-in &amp; SSO, MCP server, API &amp; tokens, Danger zone.</li><li><strong>My standups</strong> (<code>/app/me</code>) — for everyone else: today&#39;s standup with an <em>Answer in Chat</em> link, recent answers, timezone and vacation mode.</li></ul><p>Admins see the whole workspace. <strong>Managers</strong> — people who administer at least one standup — see and manage their own standups, blockers, reports and team without Workspace-admin rights. Everyone else gets the personal page.</p><h2 id="security-notes" tabindex="-1">Security notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security notes&quot;">​</a></h2><ul><li>Browser sessions are signed cookies (<code>SECRET_KEY</code>); state-changing API calls from the app carry an <code>X-Requested-With</code> header as CSRF proof.</li><li>The operator token is only ever sent as a bearer header and is never stored server-side beyond the environment variable.</li><li>Secrets (service-account key, OAuth secret, SAML certificate) are encrypted at rest and never echoed back by the API — the app only ever learns that they are set.</li><li>The API and the app share one authorisation model; see the <a href="./api.html">API guide</a> for the exact rules per endpoint.</li></ul>',11)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
